Tables
We follow this excellent short guide to making nice tables by Markus Püschel. In addition:

Lead the caption with the takeaway, then say what each column means.
Label column groups with the question or goal they answer, such as “G1: accurate?”.
Leave no empty cells in headline columns. A “–” in a key column is a gap in your evidence. Fill it.
Use counts when n is small (7/10, not 70%).
State your bold and underline rule, and shade your own method’s row.


\begin{table}[t]
  \caption{\textbf{From the monthly bill alone, \method is the most accurate on HVAC.}
    Energy accuracy (\%, higher is better) on the two appliances reported in the text, and the data each
    method needs from every home. LBM is best on the fridge. Best in \textbf{bold}.}
  \label{tab:main}
  \begin{tabular}{lccc}
    \toprule
    & \multicolumn{2}{c}{G1: accurate?} & G2: existing data only? \\
    \cmidrule(lr){2-3}\cmidrule(lr){4-4}
    Method & HVAC & Fridge & Data from each home \\
    \midrule
    FHMM & 61 & 39 & 15-minute power \\
    LBM & 56 & \textbf{72} & 15-minute power \\
    \rowcolor{gray!12} \method (ours) & \textbf{76} & 69 & \textbf{Monthly bill} \\
    \bottomrule
  \end{tabular}
\end{table}


\begin{table}[t]
  \caption{\textbf{No model matches people at telling which of two people is hotter, and fine-tuning helps only on ranking body parts.}
    Task 5 accuracy (higher is better; chance is 0.50 for two people and 0.17 for ranking three body parts)
    and Task 6 error in $^\circ$C (lower is better). Best model in each column in \textbf{bold};
    people are a reference, not a competitor.}
  \label{tab:reasoning}
  \begin{tabular}{lcccc}
    \toprule
    & \multicolumn{2}{c}{Q3: who is hotter?} & \multicolumn{2}{c}{Q4: how hot?} \\
    \cmidrule(lr){2-3}\cmidrule(lr){4-5}
    Model (parameters) & Two people & Body parts & Marker & Region \\
    \midrule
    Qwen A22 (235B)              & 0.48 & 0.34 & 3.72 & 3.40 \\
    Intern-VL 3 (38B)            & 0.64 & 0.41 & 3.63 & 2.59 \\
    Qwen-VL 2.5 (8B), zero-shot  & 0.60 & 0.32 & 2.88 & 2.85 \\
    \rowcolor{gray!12} Qwen-VL 2.5 (8B), fine-tuned on \method & 0.60 & \textbf{0.64} & 2.40 & 2.60 \\
    Gemini 3 Pro (not disclosed) & \textbf{0.74} & 0.61 & \textbf{1.86} & \textbf{1.47} \\
    \midrule
    People                       & 0.84 & 0.54 & 2.73 & 2.04 \\
    \bottomrule
  \end{tabular}
\end{table}


\begin{table}[t]
  \caption{\textbf{\method stays accurate across body types; the Apple Watch does not.}
    Error of calorie estimates (MAPE, \%, lower is better) against an indirect calorimeter,
    for all 54 participants and split by body mass index (BMI). Best in \textbf{bold}.}
  \label{tab:bmi}
  \begin{tabular}{lccc}
    \toprule
    & \multicolumn{3}{c}{G2: accurate calories?} \\
    \cmidrule(lr){2-4}
    Method & All & Normal BMI & Overweight BMI \\
    \midrule
    Apple Watch (heart rate) & 37.6 & 29.7 & 51.8 \\
    \rowcolor{gray!12} \method (breathing) & \textbf{5.8} & \textbf{5.2} & \textbf{6.9} \\
    \bottomrule
  \end{tabular}
\end{table}


\begin{table}[t]
  \caption{\textbf{TNP-D gives the most accurate predictions and, on the validation years, the best-calibrated uncertainty.}
    Negative log-likelihood (NLL) and RMSE ($\mu$g/m$^3$) of each model on held-out PM2.5; lower is better for both.
    We choose the model on validation (2009--2010); test (2011--2018) is shown too. Best in \textbf{bold}.}
  \label{tab:surrogate}
  \begin{tabular}{lcccc}
    \toprule
    & \multicolumn{2}{c}{Calibrated uncertainty? NLL} & \multicolumn{2}{c}{Accurate? RMSE} \\
    \cmidrule(lr){2-3}\cmidrule(lr){4-5}
    Model & Val. & Test & Val. & Test \\
    \midrule
    CNP              & $0.48$  & $0.98$          & 11.46         & 24.99 \\
    Random Forest    & $-0.11$ & $2.43$          & 6.55          & 15.37 \\
    Gaussian Process & $-0.19$ & $0.42$          & 5.16          & 10.31 \\
    CANP             & $-0.19$ & $0.82$          & 6.15          & 14.48 \\
    ConvCNP          & $-0.27$ & $0.59$          & 5.28          & 10.78 \\
    ConvGNP          & $-0.30$ & $1.04$          & 5.31          & 12.25 \\
    TabPFN           & $-0.37$ & $\mathbf{0.39}$ & 5.09          & 11.23 \\
    \rowcolor{gray!12} TNP-D (chosen) & $\mathbf{-0.44}$ & $0.51$ & \textbf{4.90} & \textbf{9.11} \\
    \bottomrule
  \end{tabular}
\end{table}


\begin{table}[t]
  \caption{\textbf{Kestrel is the most accurate method on phone audio, with the fewest labels.}
    Accuracy (\%, higher is better) on seen and unseen phone models, and labelled calls needed per species
    (lower is better). Best in \textbf{bold}.}
  \label{tab:main}
  \begin{tabular}{lccc}
    \toprule
    & \multicolumn{2}{c}{G1: accurate?} & G2: few labels? \\
    \cmidrule(lr){2-3}\cmidrule(lr){4-4}
    Method & Seen phones & Unseen phones & Calls / species \\
    \midrule
    Fine-tuned transformer & 61 & 55 & 100 \\
    \rowcolor{gray!12} \method (ours) & \textbf{83} & \textbf{79} & \textbf{5} \\
    \bottomrule
  \end{tabular}
\end{table}

